// To understand auto, think of it like template type deduction.
// Consider this template:
template<typename T>
void func(T param);

int i = 0;
const int ci = i;

// Case 1: auto x = ci;
// func(ci); -> T is deduced as int. So, x's type is int.
auto x = ci;

// Case 2: auto& rx = ci;
// In a template `f(T& param)`, f(ci) -> T is `const int`. So, rx is `const int&`.
auto& rx = ci;

// The ONLY difference:
autoil = {1, 2}; // OK: auto deduces std::initializer_list<int>
